import uuid
from fastapi.testclient import TestClient


def test_admin_correction_system_preserves_history(
    client: TestClient, staff_headers: dict, admin_headers: dict
):
    # 1. Staff creates feedback
    payload = {
        "client_uuid": str(uuid.uuid4()),
        "uhid": "000888123",
        "patient_name": "Kavita Rao",
        "department": "Nursing",
        "complaint_summary": "Original complaint summary generated by AI",
    }
    create_res = client.post("/api/v1/feedback", json=payload, headers=staff_headers)
    assert create_res.status_code == 201
    fb_id = create_res.json()["feedback_id"]

    # 2. Admin corrects department to Pharmacy and summary
    correction_payload = {
        "department": "Pharmacy",
        "complaint_summary": "Corrected by admin: Patient experienced medicine delay at pharmacy counter.",
    }
    patch_res = client.patch(
        f"/api/v1/admin/feedback/{fb_id}",
        json=correction_payload,
        headers=admin_headers,
    )
    assert patch_res.status_code == 200
    updated_data = patch_res.json()

    # Department changed to Pharmacy -> HOD MUST automatically re-map to Vijay Sir!
    assert updated_data["department"] == "Pharmacy"
    assert updated_data["hod_name"] == "Vijay Sir"

    # Corrections history must contain entries
    assert len(updated_data["corrections"]) >= 2
    dept_corr = next((c for c in updated_data["corrections"] if c["field_name"] == "department"), None)
    assert dept_corr is not None
    assert dept_corr["original_value"] == "Nursing"
    assert dept_corr["corrected_value"] == "Pharmacy"


def test_admin_soft_delete(client: TestClient, staff_headers: dict, admin_headers: dict):
    payload = {
        "client_uuid": str(uuid.uuid4()),
        "uhid": "000777123",
        "patient_name": "Delete Me",
        "department": "Clinical",
    }
    create_res = client.post("/api/v1/feedback", json=payload, headers=staff_headers)
    fb_id = create_res.json()["feedback_id"]

    # Soft delete
    del_res = client.delete(f"/api/v1/admin/feedback/{fb_id}", headers=admin_headers)
    assert del_res.status_code == 200

    # Ensure it no longer appears in normal feedback list
    list_res = client.get(f"/api/v1/admin/feedback?search={fb_id}", headers=admin_headers)
    assert list_res.status_code == 200
    assert list_res.json()["total"] == 0


def test_audio_privacy_and_access_control(client: TestClient, staff_headers: dict):
    """
    Section 12: Audio recordings must be access-controlled.
    Unauthenticated access must be rejected with 401.
    """
    fake_audio_id = "non-existent-or-private-audio-id"
    unauth_res = client.get(f"/api/v1/audio/{fake_audio_id}")
    assert unauth_res.status_code == 401, "Unauthenticated audio request must return 401 Unauthorized"

